import re
import numpy as np
import pandas as pd
from sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor
from sklearn.svm import SVR
from sklearn.kernel_ridge import KernelRidge
from sklearn.model_selection import GroupKFold, cross_val_predict
from sklearn.metrics import mean_absolute_error, mean_squared_error
from sklearn.base import clone
from scipy.spatial.distance import cdist
D=pd.read_csv('/work/b3_supercon_data.csv')
V='O Cu Ba Sr Y Ca La Bi Fe Nb C Pr As B Pb Ce Mo V Zn Ni'.split()
U=np.array([.697674,.454545,.333333,.285714,.4,.272727,.78,.521978,.502513,.98,.972,.265043,.5,1,.5,.28,1,.9918,1,.6])
def parse(s):
 d={}
 for e,n in re.findall(r'([A-Z][a-z]*)([0-9]*\.?[0-9]*)',s): d[e]=d.get(e,0)+float(n or 1)
 t=sum(d.values()); return {e:n/t for e,n in d.items()}
P=list(map(parse,D.composition))
E=V+sorted(set().union(*P)-set(V))
X=np.array([[p.get(e,0) for e in E] for p in P]); y=D.target.to_numpy()
groups=np.unique(X.round(9),axis=0,return_inverse=True)[1]
models={
 'RF':RandomForestRegressor(n_estimators=350,min_samples_leaf=2,max_features=.8,random_state=31,n_jobs=4),
 'ET':ExtraTreesRegressor(n_estimators=350,min_samples_leaf=2,max_features=1.0,random_state=31,n_jobs=4),
 'GB':GradientBoostingRegressor(n_estimators=250,max_depth=2,learning_rate=.035,loss='huber',random_state=31),
 'SVR':SVR(C=100,gamma=10,epsilon=3),
 'KRR':KernelRidge(alpha=.02,kernel='rbf',gamma=10),
}
def vector(formula):return np.array([parse(formula).get(e,0) for e in E])
def scenarios(x, rel=.05):
 # Each target fraction changes by +/-5%; rebalance all other fractions proportionally.
 out=[x.copy()]
 for j in range(20):
  if x[j]==0:continue
  for t in [-rel,rel]:
   v=x[j]*(1+t)
   z=x*((1-v)/(1-x[j]));z[j]=v
   if v<=U[j] and np.all(z[:20]<=U+1e-8):out.append(z)
 return np.array(out)
if __name__=='__main__':
 for name,m in models.items():
  pred=cross_val_predict(m,X,y,cv=GroupKFold(5),groups=groups,n_jobs=1)
  print(name,'CV MAE',round(mean_absolute_error(y,pred),2),'RMSE',round(mean_squared_error(y,pred)**.5,2),'high MAE',round(mean_absolute_error(y[y>=75],pred[y>=75]),2),flush=True)
  m.fit(X,y)
 forms=['Ba2Ca2Cu3O','Bi2Sr2Ca2Cu3O','Bi2Sr2Ca2Cu3O10','Bi2Sr2Ca1Cu2O10','Bi1.8Pb0.2Sr2Ca1Cu2O8','Y1Ba2Cu3O6.95','Ca0.285Sr0.665Cu1O2','Ba2Ca2Cu3O8']
 for f in forms:
  q=vector(f);s=scenarios(q)
  print('\n',f)
  for name,m in models.items():
   p=m.predict(s);print(name,'nom',round(p[0],2),'min',round(p.min(),2),'max',round(p.max(),2),end='; ')
  print('\nnearest',[(D.composition[i],y[i],round(d,3)) for i,d in sorted(enumerate(np.linalg.norm(X-q,axis=1)),key=lambda t:t[1])[:5]],flush=True)
 import pickle
 with open('/tmp/supercon_models.pkl','wb') as f:pickle.dump(models,f)

